932	func jsonExtractExpr(d DialectName, field Field) string {
933		column := qualifyColumn(d, field.Column)
934		switch d {
935		case DialectSQLite, DialectMySQL:
936			return fmt.Sprintf("JSON_EXTRACT(%s, '%s')", column, jsonPath(field))
