957		arrayExpr := jsonArrayExpr(d, field)
958		switch d {
959		case DialectSQLite:
960			return fmt.Sprintf("JSON_ARRAY_LENGTH(COALESCE(%s, JSON_ARRAY()))", arrayExpr)
961		case DialectMySQL:
962			return fmt.Sprintf("JSON_LENGTH(COALESCE(%s, JSON_ARRAY()))", arrayExpr)
963		case DialectPostgres:
964			return fmt.Sprintf("jsonb_array_length(COALESCE(%s, '[]'::jsonb))", arrayExpr)
965		default:
966			return ""
967		}
